WITH UserStats AS (SELECT U.Id AS UserId, U.DisplayName, U.Reputation, COUNT(DISTINCT P.Id) AS PostCount, SUM(COALESCE(V.VoteCount, 0)) AS TotalVotes, SUM(CASE WHEN V.VoteTypeId = 2 THEN 1 ELSE 0 END) AS UpVotes, SUM(CASE WHEN V.VoteTypeId = 3 THEN 1 ELSE 0 END) AS DownVotes FROM Users AS U LEFT JOIN Posts AS P ON U.Id = P.OwnerUserId LEFT JOIN (SELECT PostId, COUNT(*) AS VoteCount, VoteTypeId FROM Votes GROUP BY PostId, VoteTypeId) AS V ON P.Id = V.PostId WHERE U.Reputation > 1000 GROUP BY U.Id, U.DisplayName, U.Reputation), TopBadges AS (SELECT B.UserId, GROUP_CONCAT(B.Name, ', ') AS BadgeNames, COUNT(*) AS BadgeCount FROM Badges AS B GROUP BY B.UserId), PostSummary AS (SELECT P.Id AS PostId, P.Title, COALESCE(P.AcceptedAnswerId, 0) AS AcceptedAnswerId, COUNT(CASE WHEN NOT (C.Id IS NULL) THEN 1 END) AS CommentCount, MAX(P.CreationDate) AS LatestActivity, P.OwnerUserId FROM Posts AS P LEFT JOIN Comments AS C ON P.Id = C.PostId GROUP BY P.Id, P.Title, P.AcceptedAnswerId, P.OwnerUserId) SELECT U.DisplayName, U.Reputation, U.PostCount, U.TotalVotes, U.UpVotes, U.DownVotes, B.BadgeNames, B.BadgeCount, P.Title, P.CommentCount, P.LatestActivity, CASE WHEN P.AcceptedAnswerId > 0 THEN 'Accepted Answer Available' ELSE 'No Accepted Answer' END AS AnswerStatus FROM UserStats AS U LEFT JOIN TopBadges AS B ON U.UserId = B.UserId LEFT JOIN PostSummary AS P ON U.UserId = P.OwnerUserId ORDER BY U.Reputation DESC NULLS FIRST, U.TotalVotes DESC NULLS FIRST LIMIT 10